macro_rules! deps {
    () => {
        Time!();
        EdgeRef!();
        Measure!();
        Direction!();
        Edge!();
        Directed!();
        Graph!();
        MinScored!();
    };
}

macro_rules! bidirectional_dijkstra {
    () => {
        deps!();
        # [doc = " Bidirectional Dijkstra's shortest path algorithm."] # [doc = ""] # [doc = " Compute the length of the shortest path from `start` to `target`."] # [doc = ""] # [doc = " Bidirectional Dijkstra has the same time complexity as standard [`Dijkstra`][dijkstra]. However, because it"] # [doc = " searches simultaneously from both the start and goal nodes, meeting in the middle, it often"] # [doc = " explores roughly half the nodes that regular [`Dijkstra`][dijkstra] would explore. This is especially the case"] # [doc = " when the path is long relative to the graph size or when working with sparse graphs."] # [doc = ""] # [doc = " However, regular [`Dijkstra`][dijkstra] may be preferable when you need the shortest paths from the start node"] # [doc = " to multiple goals or when the start and goal are relatively close to each other."] # [doc = ""] # [doc = " The function `edge_cost` should return the cost for a particular edge, which is used"] # [doc = " to compute path costs. Edge costs must be non-negative."] # [doc = ""] # [doc = " # Arguments"] # [doc = " * `graph`: weighted graph."] # [doc = " * `start`: the start node."] # [doc = " * `goal`: the goal node."] # [doc = " * `edge_cost`: closure that returns the cost of a particular edge."] # [doc = ""] # [doc = " # Returns"] # [doc = " * `Some(K)` - the total cost from start to finish, if one was found."] # [doc = " * `None` - if such a path was not found."] # [doc = ""] # [doc = " # Complexity"] # [doc = " * Time complexity: **O((|V|+|E|)log(|V|))**."] # [doc = " * Auxiliary space: **O(|V|+|E|)**."] # [doc = ""] # [doc = " where **|V|** is the number of nodes and **|E|** is the number of edges."] # [doc = ""] # [doc = " # Example"] # [doc = " ```rust"] # [doc = " use petgraph::Graph;"] # [doc = " use petgraph::algo::bidirectional_dijkstra;"] # [doc = " use petgraph::prelude::*;"] # [doc = " use hashbrown::HashMap;"] # [doc = ""] # [doc = " let mut graph: Graph<(), (), Directed> = Graph::new();"] # [doc = " let a = graph.add_node(());"] # [doc = " let b = graph.add_node(());"] # [doc = " let c = graph.add_node(());"] # [doc = " let d = graph.add_node(());"] # [doc = " let e = graph.add_node(());"] # [doc = " let f = graph.add_node(());"] # [doc = " let g = graph.add_node(());"] # [doc = " let h = graph.add_node(());"] # [doc = ""] # [doc = " graph.extend_with_edges(&["] # [doc = "     (a, b),"] # [doc = "     (b, c),"] # [doc = "     (c, d),"] # [doc = "     (d, a),"] # [doc = "     (e, f),"] # [doc = "     (b, e),"] # [doc = "     (f, g),"] # [doc = "     (g, h),"] # [doc = "     (h, e),"] # [doc = " ]);"] # [doc = " // a ----> b ----> e ----> f"] # [doc = " // ^       |       ^       |"] # [doc = " // |       v       |       v"] # [doc = " // d <---- c       h <---- g"] # [doc = ""] # [doc = " let result = bidirectional_dijkstra(&graph, a, g, |_| 1);"] # [doc = " assert_eq!(result, Some(4));"] # [doc = " ```"] pub fn bidirectional_dijkstra < G , F , K > (graph : G , start : G :: NodeId , goal : G :: NodeId , mut edge_cost : F ,) -> Option < K > where G : Visitable + IntoEdgesDirected , G :: NodeId : Eq + Hash , F : FnMut (G :: EdgeRef) -> K , K : Measure + Copy , { let mut forward_visited = graph . visit_map () ; let mut forward_distance = HashMap :: new () ; forward_distance . insert (start , K :: default ()) ; let mut backward_visited = graph . visit_map () ; let mut backward_distance = HashMap :: new () ; backward_distance . insert (goal , K :: default ()) ; let mut forward_heap = BinaryHeap :: new () ; let mut backward_heap = BinaryHeap :: new () ; forward_heap . push (MinScored (K :: default () , start)) ; backward_heap . push (MinScored (K :: default () , goal)) ; let mut best_value = None ; while ! forward_heap . is_empty () && ! backward_heap . is_empty () { let MinScored (_ , u) = forward_heap . pop () . unwrap () ; let MinScored (_ , v) = backward_heap . pop () . unwrap () ; forward_visited . visit (u) ; backward_visited . visit (v) ; let distance_to_u = forward_distance [& u] ; let distance_to_v = backward_distance [& v] ; for edge in graph . edges_directed (u , Direction :: Outgoing) { let x = edge . target () ; let current_edge_cost = edge_cost (edge) ; if ! forward_visited . is_visited (& x) { let next_score = distance_to_u + current_edge_cost ; match forward_distance . entry (x) { Occupied (entry) => { if next_score < * entry . get () { * entry . into_mut () = next_score ; forward_heap . push (MinScored (next_score , x)) ; } } Vacant (entry) => { entry . insert (next_score) ; forward_heap . push (MinScored (next_score , x)) ; } } } if ! backward_visited . is_visited (& x) { continue ; } let potential_best_value = distance_to_u + current_edge_cost + backward_distance [& x] ; let improves_best_value = match best_value { None => true , Some (current_best_value) => potential_best_value < current_best_value , } ; if improves_best_value { best_value = Some (potential_best_value) ; } } for edge in graph . edges_directed (v , Direction :: Incoming) { let x = edge . source () ; let edge_cost = edge_cost (edge) ; if ! backward_visited . is_visited (& x) { let next_score = distance_to_v + edge_cost ; match backward_distance . entry (x) { Occupied (entry) => { if next_score < * entry . get () { * entry . into_mut () = next_score ; backward_heap . push (MinScored (next_score , x)) ; } } Vacant (entry) => { entry . insert (next_score) ; backward_heap . push (MinScored (next_score , x)) ; } } } if ! forward_visited . is_visited (& x) { continue ; } let potential_best_value = distance_to_v + edge_cost + forward_distance [& x] ; let improves_best_value = match best_value { None => true , Some (mu) => potential_best_value < mu , } ; if improves_best_value { best_value = Some (potential_best_value) ; } } if let Some (best_value) = best_value { if distance_to_u + distance_to_v >= best_value { return Some (best_value) ; } } } None }
    };
}

bidirectional_dijkstra!();